3	namespace App\Filament\Exports;
4	
5	use App\Enums\AwardRedeemStatus;
6	use App\Models\AwardRedeem;
7	use Carbon\CarbonInterface;
8	use Filament\Actions\Exports\ExportColumn;
9	use Filament\Actions\Exports\Exporter;
10	use Filament\Actions\Exports\Models\Export;
11	
12	class AwardRedeemExporter extends Exporter
13	{
14	    protected static ?string $model = AwardRedeem::class;
15	
16	    public static function getColumns(): array
17	    {
18	        return [
19	            ExportColumn::make('uuid')
20	                ->label('Identificativo univoco'),
21	            ExportColumn::make('status')->label('Stato')
22	                ->formatStateUsing(fn (AwardRedeemStatus $state): string => $state->getLabel()),
23	            ExportColumn::make('requested_at')->label('Data richiesta')
24	                ->formatStateUsing(
25	                    fn (?CarbonInterface $state): string => $state?->timezone('Europe/Rome')->format('d/m/Y H:i') ?? 'N/A'
26	                ),
27	            ExportColumn::make('award_name')->label('Premio'),
28	            ExportColumn::make('user_lastname')->label('Cognome'),
29	            ExportColumn::make('user_firstname')->label('Nome'),
30	            ExportColumn::make('user_address')->label('Indirizzo'),
31	            ExportColumn::make('user_address_number')->label('Numero civico'),
32	            ExportColumn::make('user_postcode')->label('CAP'),
33	            ExportColumn::make('user_city')->label('Città'),
34	            ExportColumn::make('user_province')->label('Provincia'),
35	            // ExportColumn::make('user_country'),
36	            ExportColumn::make('user_email')->label('Email'),
37	            ExportColumn::make('user_phone')->label('Telefono'),
38	            ExportColumn::make('rejected_at')->label('Data cancellazione')
39	                ->formatStateUsing(
40	                    fn (?CarbonInterface $state): string => $state?->timezone('Europe/Rome')->format('d/m/Y H:i') ?? 'N/A'
41	                ),
42	            ExportColumn::make('approved_at')->label('Data approvazione')
43	                ->formatStateUsing(
44	                    fn (?CarbonInterface $state): string => $state?->timezone('Europe/Rome')->format('d/m/Y H:i') ?? 'N/A'
45	                ),
46	            // ExportColumn::make('reject_reason'),
47	        ];
48	    }
49	
50	    public function getJobRetryUntil(): ?CarbonInterface
51	    {
52	        return now()->add('5 minutes');
53	    }
54	
55	    /**
56	     * With the `sync` connection, the export will be processed immediately
57	     * and returned into a notification.
58	     */
59	    public function getJobConnection(): ?string
60	    {
61	        return 'sync';
62	    }
63	
64	    public static function getCompletedNotificationBody(Export $export): string
65	    {
66	        $body = 'Esportazione completata. Righe esportate: ' . number_format($export->successful_rows);
67	
68	        if ($failedRowsCount = $export->getFailedRowsCount()) {
69	            $body .= ' Righe non esportate: ' . number_format($failedRowsCount);
70	        }
71	
72	        return $body;
73	    }
74	}
